"""matplotlib.axis — Axis classes (real-behaviour shim).

The shim's Axis tracks its own locator/formatter pair (per major/minor),
its own view & data intervals, and its own scale. ``get_majorticklocs()``
actually invokes the locator over the current view interval, so callers
that drive the gridline / tick-label pipeline get real positions rather
than empty lists.
"""

from matplotlib.artist import Artist


# Used internally by matplotlib's grid renderer to subdivide gridlines
# when drawn on a curved (e.g. polar) axis. Plotly handles gridlines
# itself, so this is purely informational.
GRIDLINE_INTERPOLATION_STEPS = 180


class Ticker:
    """Pairing of a locator and a formatter, used by :class:`Axis`'s
    ``majorTicks`` / ``minorTicks`` slots."""

    def __init__(self, locator=None, formatter=None):
        self._locator = locator
        self._formatter = formatter

    @property
    def locator(self):       return self._locator
    @locator.setter
    def locator(self, l):    self._locator = l

    @property
    def formatter(self):     return self._formatter
    @formatter.setter
    def formatter(self, f):  self._formatter = f


class Axis(Artist):
    """Axis common to X and Y. Holds its own scale, view/data intervals,
    major/minor locator+formatter pair, and any user-supplied tick
    overrides. Returns real tick positions and labels from the locator
    when called."""

    OFFSETTEXTPAD = 3
    axis_name = ''

    # Class-level defaults (instances override in __init__).
    pickradius = 15
    remove_overlapping_locs = True
    isDefault_majfmt = True
    isDefault_minfmt = True
    isDefault_majloc = True
    isDefault_minloc = True
    isDefault_label = True

    def __init__(self, axes, **kwargs):
        super().__init__()
        self.axes = axes
        # Lazy-import to avoid circular dep at module-load time.
        from matplotlib.ticker import (AutoLocator, AutoMinorLocator,
                                        ScalarFormatter, NullFormatter)
        self.major = Ticker(AutoLocator(), ScalarFormatter())
        self.minor = Ticker(AutoMinorLocator(), NullFormatter())
        # Bind locators/formatters to this axis so they can read view_interval.
        for tk in (self.major, self.minor):
            try:
                tk.locator.set_axis(self)
                tk.formatter.set_axis(self)
            except Exception:
                pass

        self._label = None
        self._label_text = ''
        self._label_position = 'bottom' if self.axis_name == 'x' else 'left'
        self._visible = True
        self._scale = 'linear'
        self._inverted = False
        self._view_interval = (0.0, 1.0)
        self._data_interval = (0.0, 1.0)
        # User-supplied tick overrides (None → locator drives ticks).
        self._user_ticks = None
        self._user_ticklabels = None
        self._tick_params = {}
        self._grid_visible = False
        self._grid_kwargs = {}
        self._pickradius = 15
        self._url = None
        self._units = None
        self._converter = None
        # Per-instance tick lists.
        self.majorTicks = []
        self.minorTicks = []

    # ── Locator / Formatter ─────────────────────────────────────────
    def set_major_locator(self, locator):
        self.major.locator = locator
        try: locator.set_axis(self)
        except Exception: pass
        self.isDefault_majloc = False

    def set_minor_locator(self, locator):
        self.minor.locator = locator
        try: locator.set_axis(self)
        except Exception: pass
        self.isDefault_minloc = False

    def set_major_formatter(self, formatter):
        self.major.formatter = formatter
        try: formatter.set_axis(self)
        except Exception: pass
        self.isDefault_majfmt = False

    def set_minor_formatter(self, formatter):
        self.minor.formatter = formatter
        try: formatter.set_axis(self)
        except Exception: pass
        self.isDefault_minfmt = False

    def get_major_locator(self):   return self.major.locator
    def get_minor_locator(self):   return self.minor.locator
    def get_major_formatter(self): return self.major.formatter
    def get_minor_formatter(self): return self.minor.formatter

    # ── Tick positions ──────────────────────────────────────────────
    def get_majorticklocs(self):
        """Return the actual major tick positions for the current
        view interval. Honors user-supplied set_ticks() override."""
        if self._user_ticks is not None:
            return list(self._user_ticks)
        loc = self.major.locator
        if loc is None: return []
        try:
            vmin, vmax = self.get_view_interval()
            return list(loc.tick_values(vmin, vmax))
        except Exception:
            return []

    def get_minorticklocs(self):
        loc = self.minor.locator
        if loc is None: return []
        try:
            vmin, vmax = self.get_view_interval()
            return list(loc.tick_values(vmin, vmax))
        except Exception:
            return []

    def get_ticklocs(self, minor=False):
        return self.get_minorticklocs() if minor else self.get_majorticklocs()

    # ── Tick label strings ─────────────────────────────────────────
    def get_majorticklabels(self):
        if self._user_ticklabels is not None:
            return list(self._user_ticklabels)
        fmt = self.major.formatter
        if fmt is None: return []
        locs = self.get_majorticklocs()
        try:
            return [fmt(v, i) for i, v in enumerate(locs)]
        except Exception:
            return [str(v) for v in locs]

    def get_minorticklabels(self):
        fmt = self.minor.formatter
        if fmt is None: return []
        locs = self.get_minorticklocs()
        try:
            return [fmt(v, i) for i, v in enumerate(locs)]
        except Exception:
            return [str(v) for v in locs]

    def get_ticklabels(self, minor=False, which=None):
        if which == 'minor' or (minor and which is None):
            return self.get_minorticklabels()
        return self.get_majorticklabels()

    def set_ticklabels(self, labels, *, minor=False, **kwargs):
        self._user_ticklabels = [str(l) for l in labels]

    # ── User-overridable ticks ─────────────────────────────────────
    def set_ticks(self, ticks, labels=None, *, minor=False, **kwargs):
        if minor:
            from matplotlib.ticker import FixedLocator
            self.minor.locator = FixedLocator(list(ticks))
            self.minor.locator.set_axis(self)
        else:
            self._user_ticks = list(ticks)
        if labels is not None:
            self._user_ticklabels = [str(l) for l in labels]

    def get_ticks(self, minor=False):
        return self.get_minorticklocs() if minor else self.get_majorticklocs()

    # ── Tick objects (lightweight, populated lazily) ───────────────
    def get_major_ticks(self, numticks=None):
        locs = self.get_majorticklocs()
        if numticks is not None:
            locs = locs[:numticks]
        TickCls = XTick if self.axis_name == 'x' else YTick
        self.majorTicks = [TickCls(self.axes, l) for l in locs]
        return self.majorTicks

    def get_minor_ticks(self, numticks=None):
        locs = self.get_minorticklocs()
        if numticks is not None:
            locs = locs[:numticks]
        TickCls = XTick if self.axis_name == 'x' else YTick
        self.minorTicks = [TickCls(self.axes, l) for l in locs]
        return self.minorTicks

    # ── Tick parameters ────────────────────────────────────────────
    def get_tick_params(self, which='major'):
        return dict(self._tick_params.get(which, {}))

    def set_tick_params(self, which='major', reset=False, **kwargs):
        if reset:
            self._tick_params[which] = {}
        self._tick_params.setdefault(which, {}).update(kwargs)

    # ── Label text ─────────────────────────────────────────────────
    def set_label_text(self, label, **kwargs):
        self._label_text = str(label) if label is not None else ''
        self.isDefault_label = False
        return self._label_text

    def get_label_text(self):
        return self._label_text

    def set_label(self, label):
        self._label = label

    def set_label_position(self, position):
        self._label_position = position

    def get_label_position(self):
        return self._label_position

    def set_label_coords(self, x, y=None, transform=None):
        self._label_coords = (x, y)

    # ── Visibility ─────────────────────────────────────────────────
    def set_visible(self, b):  self._visible = bool(b)
    def get_visible(self):     return self._visible

    # ── Tick position ──────────────────────────────────────────────
    def set_ticks_position(self, position): self._tick_position = position

    # ── Grid ───────────────────────────────────────────────────────
    def grid(self, visible=None, which='major', **kwargs):
        if visible is not None:
            self._grid_visible = bool(visible)
        self._grid_kwargs[which] = dict(kwargs)

    # ── Inversion ──────────────────────────────────────────────────
    def set_inverted(self, inverted):
        self._inverted = bool(inverted)

    def get_inverted(self):
        return self._inverted

    # ── Scale ──────────────────────────────────────────────────────
    def set_scale(self, value, **kwargs):
        self._scale = value
        # Auto-switch the locator/formatter to log-friendly ones
        # when entering log mode (mirrors upstream behaviour).
        from matplotlib.ticker import (LogLocator, LogFormatterSciNotation,
                                        AutoLocator, ScalarFormatter)
        if value == 'log':
            self.major.locator = LogLocator()
            self.major.formatter = LogFormatterSciNotation()
            self.major.locator.set_axis(self)
        elif value == 'linear':
            self.major.locator = AutoLocator()
            self.major.formatter = ScalarFormatter()
            self.major.locator.set_axis(self)

    def get_scale(self):
        return self._scale

    # ── View / data intervals ──────────────────────────────────────
    def get_view_interval(self):
        return self._view_interval

    def set_view_interval(self, vmin, vmax, ignore=False):
        if ignore:
            self._view_interval = (float(vmin), float(vmax))
        else:
            old_min, old_max = self._view_interval
            self._view_interval = (min(float(vmin), old_min),
                                    max(float(vmax), old_max))

    def get_data_interval(self):
        return self._data_interval

    def set_data_interval(self, vmin, vmax, ignore=False):
        if ignore:
            self._data_interval = (float(vmin), float(vmax))
        else:
            old_min, old_max = self._data_interval
            self._data_interval = (min(float(vmin), old_min),
                                    max(float(vmax), old_max))

    def set_default_intervals(self):
        self._view_interval = (0.0, 1.0)
        self._data_interval = (0.0, 1.0)

    # ── Units / converters ─────────────────────────────────────────
    def have_units(self):
        return self._converter is not None
    def get_units(self):
        return self._units
    def set_units(self, u):
        self._units = u
    def convert_units(self, x):
        if self._converter is None: return x
        try: return self._converter.convert(x, self._units, self)
        except Exception: return x
    def update_units(self, data):
        return False
    def axis_date(self, tz=None):
        try:
            from matplotlib.dates import DateConverter
            self._converter = DateConverter()
        except Exception:
            pass

    # ── Misc getters used by other modules ─────────────────────────
    def get_gridlines(self):      return []
    def get_majorticklines(self): return []
    def get_minorticklines(self): return []
    def get_ticklines(self, minor=False): return []
    def get_minpos(self):         return 0.0
    def get_offset_text(self):
        from matplotlib.text import Text
        return Text(0, 0, '')
    def get_pickradius(self):     return self._pickradius
    def set_pickradius(self, p):  self._pickradius = int(p)
    def get_remove_overlapping_locs(self): return True
    def set_remove_overlapping_locs(self, val): pass
    def get_tick_padding(self):   return 0.0
    def get_tick_space(self):     return 9
    def get_ticks_direction(self, minor=False):
        return ['out'] * len(self.get_minorticklocs() if minor
                              else self.get_majorticklocs())
    def get_url(self):            return self._url
    def set_url(self, url):       self._url = url
    def reset_ticks(self):
        self.majorTicks = []
        self.minorTicks = []
    def clear(self):
        self.reset_ticks()
        self._view_interval = (0.0, 1.0)
        self._data_interval = (0.0, 1.0)
        self._user_ticks = None
        self._user_ticklabels = None
    def set_clip_path(self, clippath, transform=None): pass
    def set_offset_position(self, position): pass
    def set_smart_bounds(self, val): pass
    def zoom(self, direction): pass
    def axes_locator(self): return None
    def get_tightbbox(self, renderer=None, *, for_layout_only=False):
        return None
    def limit_range_for_scale(self, vmin, vmax):
        return (vmin, vmax)
    def minorticks_on(self):
        from matplotlib.ticker import AutoMinorLocator
        self.minor.locator = AutoMinorLocator()
        self.minor.locator.set_axis(self)
    def minorticks_off(self):
        from matplotlib.ticker import NullLocator
        self.minor.locator = NullLocator()


class XAxis(Axis):
    __name__ = 'xaxis'
    axis_name = 'x'

    def tick_bottom(self):
        self.set_ticks_position('bottom')
    def tick_top(self):
        self.set_ticks_position('top')
    def get_ticks_position(self):
        return getattr(self, '_tick_position', 'bottom')


class YAxis(Axis):
    __name__ = 'yaxis'
    axis_name = 'y'

    def tick_left(self):
        self.set_ticks_position('left')
    def tick_right(self):
        self.set_ticks_position('right')
    def get_ticks_position(self):
        return getattr(self, '_tick_position', 'left')
    def set_offset_position(self, position):
        self._offset_position = position


class Tick(Artist):
    """A single tick. Holds its location and (optionally) two label
    strings — upstream supports primary ('label1') and secondary
    ('label2') labels per tick."""

    def __init__(self, axes, loc, **kwargs):
        super().__init__()
        self.axes = axes
        self._loc = float(loc)
        self.label1 = None
        self.label2 = None
        self._pad = 0.0
        self._tickdir = 'in'

    def get_loc(self):           return self._loc
    def set_label1(self, s):     self.label1 = s
    def set_label2(self, s):     self.label2 = s
    def get_pad(self):           return self._pad
    def set_pad(self, val):      self._pad = float(val)
    def update_position(self, loc):
        self._loc = float(loc)
    def get_view_interval(self):
        return (0.0, 1.0)
    def get_tickdir(self):       return self._tickdir
    def get_tick_padding(self):  return self._pad


class XTick(Tick):
    __name__ = 'xtick'
    axis_name = 'x'


class YTick(Tick):
    __name__ = 'ytick'
    axis_name = 'y'
